namespace App\Domain\Billing;

/**
 * Accurate decimal arithmetic based on bcmath.
 *
 * All monetary operations are performed with strings —
 * the float type is not involved anywhere.
 */
final class DecimalMath
{
    /** Working precision for intermediate computations. */
    public const SCALE = 16;

    /** Number of decimal places for event cost. */
    public const COST_SCALE = 6;

    /** Division by 1,000,000 tokens. */
    private const TOKENS_UNIT = '1000000';

    /**
     * HALF_UP rounding of an exact decimal value to the specified
     * number of decimal places (2.5 → 3).
     */
    public static function roundHalfUp(string $value, int $scale = self::COST_SCALE): string
    {
        $negative = str_starts_with($value, '-');
        $absolute = $negative ? substr($value, 1) : $value;
        $absolute = bcadd($absolute, '0', $scale + 1);      // exactly $scale+1 decimal places (truncate the tail)
        $boundaryDigit = (int) substr($absolute, -1);        // the first discarded digit
        $base = substr($absolute, 0, -1);                    // exactly $scale decimal places
        $rounded = $boundaryDigit >= 5 ? bcadd($base, self::unitOne($scale)) : $base;
        return $rounded === '-0' ? '0' : ($negative && $rounded !== '0' ? '-'.$rounded : $rounded);
    }
