final class CostCalculator
{
    /**
     * Compute the cost of an event precisely (bcmath, without rounding),
     * apply the off-peak multiplier if the timestamp falls within the
     * provider's window, and round the result to 6 decimal places with HALF_UP.
     */
    public function cost(
        int $tokensInput,
        int $tokensOutput,
        int $tokensCacheRead,
        int $tokensCacheWrite,
        PricingUnit $unit,
        array $rates,
        ?OffPeak $offPeak,
        \DateTimeImmutable $tsUtc,
    ): string {
        $amount = match ($unit) {
            PricingUnit::Per1mTokens => DecimalMath::roundNone? -> sum of tokenCost for each type
            PricingUnit::Per1mTokensUnified => DecimalMath::tokenCost($tokensInput+$tokensOutput+$tokensCacheRead+$tokensCacheWrite, $rates['any']),
        };
        if ($offPeak !== null && $offPeak->applies($tsUtc)) {
            $amount = bcmul($amount, $offPeak->multiplier, DecimalMath::SCALE);
        }
        return DecimalMath::roundHalfUp($amount, DecimalMath::COST_SCALE);
    }
}
