OffPeak:

```php
final class OffPeak
{
    public function __construct(
        private readonly string $windowStart, // "HH:MM"
        private readonly string $windowEnd,   // "HH:MM"
        private readonly string $multiplier,  // decimal string ≥ 0
    ) {}

    public function multiplier(): string => $this->multiplier;

    public function applies(\DateTimeImmutable $tsUtc): bool
    {
        $t = (int) $tsUtc->format('G') * 60 + (int) $tsUtc->format('i');
        $start = self::toMinutes($this->windowStart);
        $end = self::toMinutes($this->windowEnd);
        if ($start === $end) {
            return false; // an empty interval [x, x) contains nothing
        }
        if ($start < $end) {
            return $t >= $start && $t < $end;
        }
        return $t >= $start || $t < $end; // the window crosses midnight
    }

    public static function toMinutes(string $hm): int
    {
        [$h, $m] = explode(':', $hm);
        return (int) $h * 60 + (int) $m;
    }
}
```

