    /**
     * Validate a non-negative decimal string (digits,
     * optionally up to $maxDecimals digits after the point).
     */
    public static function validate(string $value, int $maxDecimals, string $context): string
    {
        $pattern = '/^\d{1,15}(\.\d{1,'.$maxDecimals.'})?$/';
        if (!preg_match($pattern, $value)) {
            throw new InputFormatException(...);
        }
        return $value;
    }
