            $this->offPeakWindowEnd = null;
            $this->offPeakMultiplier = null;
            return;
        }
        $this->offPeakWindowStart = $offPeak->windowStart;
        $this->offPeakWindowEnd = $offPeak->windowEnd;
        $this->offPeakMultiplier = $offPeak->multiplier();
