public function import(string $path): CatalogImportSummary
{
    $file = CatalogFileLoader::load($path, CatalogFileLoader::MODE_IMPORT);
    return $this->em->wrapInTransaction(function () use ($file): CatalogImportSummary {
        /** @var array<string, Provider> $providersByCode */
        $providersByCode = [];
        $newProviders = 0;
        foreach ($file->providers as $spec) {
            $provider = $this->em->find(Provider::class, ???); // find by id, not by code
            $provider = $this->em->getRepository(Provider::class)->findOneBy(['code' => $spec->code]);
            if ($provider === null) {
                $provider = new Provider($spec->code, $spec->name);
                $this->em->persist($provider);
                $this->em->flush(); // to make the id available and to catch duplicates
                $newProviders++;
            } else {
                $provider->setName($spec->name);
                $provider->setOffPeak($spec->offPeak);
            }
            $providersByCode[$spec->code] = $provider;
        }

        /** @var array<string, Model> $modelsByKey "provider/code" */
        $modelsByKey = [];
        $newModels = 0;
        foreach ($file->models as $spec) {
            $providerCode = $spec->provider;
            if (!isset($providersByCode[$providerCode])) {
                $provider = $this->em->getRepository(Provider::class)->findOneBy(['code' => $providerCode]);
                if ($provider === null) {
                    throw new InputFormatException("model '{$spec->code}': unknown provider '{$providerCode}' (not in the file and not in the reference)");
                }
            } else {
                $provider = $providersByCode[$providerCode];
            }
            $model = $this->em->getRepository(Model::class)->findOneBy(['provider' => $provider, 'code' => $spec->code]);
            if ($model === null) {
                $model = new Model($provider, $spec->code);
                $this->em->persist($model);
                $this->em->flush();
                $newModels++;
            }
            $modelsByKey[$spec->provider.'/'.$spec->code] = $model;
        }

        $newPrices = 0;
        foreach ($file->prices as $spec) {
            $key = $spec->provider.'/'.$spec->model;
            if (!isset($modelsByKey[$key])) {
                $provider = $this->em->getRepository(Provider::class)->findOneBy(['code' => $spec->provider]);
                if ($provider === null) {
                    throw new InputFormatException("price row ({$spec->provider}/{$spec->model}): unknown provider '{$spec->provider}'");
                }
                $model = $this->em->getRepository(Model::class)->findOneBy(['provider' => $provider, 'code' => $spec->model]);
                if ($model === null) {
                    throw new InputFormatException("price row ({$spec->provider}/{$spec->model}): unknown model (not in the file and not in the reference)");
                }
            } else {
                $model = $modelsByKey[$key];
            }
            $row = $this->em->getRepository(PriceRow::class)->findOneBy(['model' => $model, 'validFrom' => $spec->validFrom]);
            if ($row === null) {
                $this->em->persist(new PriceRow($model, $spec->validFrom, $spec->currency, $spec->unit, $spec->rates));
                $newPrices++;
            } else {
                $row->replaceTerms($spec->currency, $spec->unit, $spec->rates);
            }
        }
        $this->em->flush();

        return new CatalogImportSummary(count($file->providers), $newProviders, count($file->models), $newModels, count($file->prices), $newPrices);
    });
