            $sql = 'INSERT INTO usage_events
                        (provider_code, provider_request_id, model_code, user, ts, ts_raw,
                         tokens_input, tokens_output, tokens_cache_read, tokens_cache_write,
                         status)
                     VALUES
                        (:code, :rid, :model, :user, :ts, :ts_raw,
                         :tin, :tout, :tcr, :tcw,
                         ' . EventStatus::Pending->value . ')
                     ON CONFLICT (provider_code, provider_request_id) DO NOTHING';
            $stmt = $this->connection->prepare($sql);
            foreach ($events as $e) {
                $affected = $stmt->execute([
                    'code' => $e['provider'],
                    'rid' => $e['provider_request_id'],
                    'model' => $e['model'],
                    'user' => $e['user'],
                    'ts' => $e['ts_utc'], // DateTimeImmutable — DBAL converts it
                    'ts_raw' => $e['ts_raw'],
                    'tin' => $e['tokens_input'],
                    'tout' => $e['tokens_output'],
                    'tcr' => $e['tokens_cache_read'],
                    'tcw' => $e['tokens_cache_write'],
