```php
final class UsageFile
{
    /** @return list<array<string, mixed>> */
    public static function parse(string $path): array
    {
        if (!is_file($path) || !is_readable($path)) throw new InputFormatException(...);
        $fh = fopen($path, 'rb');
        $events = [];
        $lineNo = 0;
        while (($line = fgets($fh)) !== false) {
            $lineNo++;
            $trimmed = trim($line);
            if ($trimmed === '') continue; // an empty line (e.g., a trailing one) is not an event
            $events[] = self::parseLine($trimmed, $path, $lineNo);
        }
        fclose($fh);
        return $events;
    }

    private static function parseLine(string $line, string $path, int $lineNo): array
    {
        $context = $path.':'.$lineNo;
        try {
            $data = json_decode($line, true, 64, JSON_THROW_ON_ERROR);
        } catch (\JsonException $e) {
            throw new InputFormatException('line '.$lineNo.' of '.$path.': invalid JSON: '.$e->getMessage());
        }
        if (!is_array($data)) throw new InputFormatException('line '.$lineNo.' of '.$path.': the event must be a JSON object');
        $ctx = $path.':'.$lineNo;
        $provider = self::nonEmptyString($data, 'provider', $ctx);
        $rid = self::nonEmptyString($data, 'provider_request_id', $ctx);
        $model = self::nonEmptyString($data, 'model', $ctx);
        $user = self::nonEmptyString($data, 'user', $ctx);
        $tsRaw = self::nonEmptyString($data, 'ts', $ctx);
        $tsUtc = IsoUtc::parse($tsRaw, $ctx);
        return [
            'provider' => $provider,
            'provider_request_id' => $rid,
            'model' => $model,
            'user' => $user,
            'ts_utc' => $tsUtc,
            'ts_raw' => $tsRaw,
            'tokens_input' => self::tokenCount($data, 'tokens_input', $ctx),
            'tokens_output' => self::tokenCount($data, 'tokens_output', $ctx),
            'tokens_cache_read' => self::tokenCount($data, 'tokens_cache_read', $ctx),
            'tokens_cache_write' => self::tokenCount($data, 'tokens_cache_write', $ctx),
        ];
    }

    private static function tokenCount(array $data, string $key, string $ctx): int
    {
        if (!isset($data[$key]) || !is_int($data[$key]) || $data[$key] < 0) {
            throw new InputFormatException($ctx.": {$key}: an integer ≥ 0 is required");
        }
        return $data[$key];
    }
}
```

