final class RepriceService
{
    public function __construct(private readonly EntityManagerInterface $em) {}

    public function reprice(string $path): RepriceSummary
    {
        $file = CatalogFileLoader::load($path, CatalogFileLoader::MODE_REPRICE);
        return $this->em->wrapInTransaction(function () use ($file): RepriceSummary {
            /** @var array<int, PriceRow> $touched */
            $touched = [];
            /** @var array<string, Provider> $providersByCode */
            $providersByCode = [];

            foreach ($file->prices as $spec) {
                $provider = $providersByCode[$spec->provider] ??= $this->em->getRepository(Provider::class)->findOneBy(['code' => $spec->provider]);
                if ($provider === null) {
                    throw new InputFormatException("price row ({$spec->provider}/{$spec->model}, valid_from {$spec->validFrom->format(...)}): provider '{$spec->provider}' is not in the reference");
                }
                $model = $this->em->getRepository(Model::class)->findOneBy(['provider' => $provider, 'code' => $spec->model]);
                if ($model === null) {
                    throw new InputFormatException("... model not in the reference");
                }
                $row = $this->em->getRepository(PriceRow::class)->findOneBy(['model' => $model, 'validFrom' => $spec->validFrom]);
                if ($row === null) {
                    $row = new PriceRow($model, $spec->validFrom, $spec->currency, $spec->unit, $spec->rates);
                    $this->em->persist($row);
                    $this->em->flush();
                } else {
                    $row->replaceTerms($spec->currency, $spec->unit, $spec->rates);
                }
                $touched[$row->id()] = $row;
            }

            $calculator = new CostCalculator();
            $count = 0;
            $delta = '0.000000';
            if (count($touched) > 0) {
                /** @var UsageEvent[] $events */
                $events = $this->em->createQueryBuilder()
                    ->select('e')->from(UsageEvent::class, 'e')
                    ->where('e.status = :status')->setParameter('status', EventStatus::Rated)
                    ->andWhere('e.priceRow IN (:rows)') // a DQL entity parameter IN with an array ✓
                    ->setParameter('rows', array_values($touched))
                    ->getQuery()->getResult();
                foreach ($events as $event) {
                    $row = $event->priceRow();
                    $newCost = $calculator->cost(
                        $event->tokensInput(), ...,
                        $row->unit(), $row->rates(),
                        $this->em->getRepository(Provider::class)->findOneBy(['code' => $event->providerCode()])?->offPeak(),
                        $event->ts(),
                    );
                    if ($newCost !== $event->cost()) {
                        $event->setCost($newCost);
                    }
                    $delta = bcadd($delta, bcsub($newCost, (string) $event->cost(), 6), 6);
                    $count++;
                }
            }
            $this->em->flush();
            return new RepriceSummary($count, $delta);
        });
    }
}
