```php
    private static function readOffPeak(array $entry, string $ctx): ?OffPeak
    {
        if (!array_key_exists('off_peak', $entry)) {
            return null; // treat as absent = no discount
        }
        $off = $entry['off_peak'];
        if ($off === null) return null;
        if (!is_array($off)) throw new InputFormatException($ctx.': off_peak: an object or null is required');
        $start = self::windowBound($off, 'window_start', $ctx);
        $end = self::windowBound($off, 'window_end', $ctx);
        $multiplier = Decimals::validate((string ...), 16, $ctx.':off_peak.multiplier');
        if (!is_string($entry's multiplier raw value)) error
        if (bccomp(multiplier, '0') < 0) error (negative numbers are rejected by the regex anyway)
        return new OffPeak($start, $end, $multiplier);
    }

    private static function windowBound(array $off, string $key, string $ctx): string
    {
        $v = $off[$key] ?? null;
        if (!is_string($v) || !preg_match('/^([01][0-9]|2[0-3]):[0-5]\d$/', $v)) {
            throw new InputFormatException($ctx.':off_peak.'.$key.': "HH:MM" format required');
        }
        return $v;
    }
